def solve(inputs: dict) -> float:
    M = inputs['M']
    n = inputs['n']
    mod = inputs['mod']

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, n, mod):
        """Compute M^n modulo mod using binary exponentiation"""
        # Start with identity matrix
        result = [[1, 0], [0, 1]]
        base = [row[:] for row in M]  # Copy M

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    # Compute M^n
    result = matrix_pow(M, n, mod)

    # Sum all entries
    total = sum(result[i][j] for i in range(2) for j in range(2))

    return total % mod
