    steps = inputs['steps']

    # Mask to keep within 32 bits
    mask_32 = (1 << 32) - 1

    for _ in range(steps):
        X ^= (X << 13) & mask_32
        X ^= (X >> 7)
        X ^= (X << 15) & mask_32
        X &= mask_32  # Keep within 32 bits

